def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, 63)
        return min(budget, 28)

    total_alive = 1 + len(alive_opponents)
    expected_winners = max(1, int(supply // WATER_REQ))
    scarcity = total_alive - expected_winners

    prev_bids = []
    desperate_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opponents += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opponents += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            status = prev.get('status')
            hp_after = prev.get('hp_after')
            if status == 'failed' or (hp_after is not None and hp_after <= 2):
                desperate_opponents += 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 2 or no_water_days >= 2:
        target = max(60, highest_prev + 2)
    elif hp <= 4 or no_water_days >= 1:
        target = max(45, avg_prev + 3)
    else:
        if scarcity >= 2:
            target = max(36, avg_prev + 2)
        elif scarcity == 1:
            target = max(28, avg_prev + 1)
        else:
            target = 18

    if desperate_opponents >= expected_winners:
        target += 8
    elif desperate_opponents == 0 and scarcity <= 1:
        target -= 4

    if highest_prev >= 60 and hp > 4 and no_water_days == 0:
        target = min(target, 26)

    if rich_opponents >= len(alive_opponents) and hp > 3 and no_water_days == 0:
        target = min(target, 30)

    if budget < DAILY_SALARY:
        target = min(target, budget * 0.75)

    target = max(0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opponents = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((opp_id, o))

    # Estimate expected water needed: if we've already gone without water, bid more.
    urgency = 0
    if no_water_days is not None:
        urgency = int(no_water_days)

    # React to yesterday's bids if available.
    yesterday_bids = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Base bid target tied to supply level.
    # If supply is near max, we can try to win with moderate bid; if near min, bid more conservatively to avoid overpaying.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (float(supply) - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    # supply_norm in [0,1] ideally
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Conservative default: aim around 55% salary.
    base = DAILY_SALARY * (0.45 + 0.15 * supply_norm)

    # If hp is low, increase bid.
    if hp is not None and hp <= 2:
        base = DAILY_SALARY * 0.85
    elif hp is not None and hp <= 3:
        base = DAILY_SALARY * 0.65

    # If we've already had no water days, ramp up.
    if urgency >= 2:
        base = max(base, DAILY_SALARY * 0.8)
    elif urgency == 1:
        base = max(base, DAILY_SALARY * 0.6)

    # If we can see opponent yesterday bids, slightly outbid when they were high.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents were bidding aggressively, we match slightly above if we must.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp is not None and hp > 3:
                base = max(base, DAILY_SALARY * 0.35)
            else:
                base = max(base, DAILY_SALARY * 0.95)
        else:
            base = max(base, highest_prev_bid + 1.5)

    # Final cap by budget; also avoid bidding above what we can pay.
    bid = min(float(budget), float(base))

    # Ensure non-negative.
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
